from typing import List

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        NEG = -10**18
        P = [0] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] + nums[i]

        # f[i][j]: max sum using j subarrays within first i elements
        f = [[NEG] * (k + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            f[i][0] = 0

        # M[j] = max over eligible starts s of f[s][j-1] - P[s]
        M = [NEG] * (k + 1)

        for i in range(n):
            # New eligible start for a subarray ending at index i: s = i+1-m
            s = i + 1 - m
            if s >= 0:
                fs = f[s]
                for j in range(1, k + 1):
                    val = fs[j - 1] - P[s]
                    if val > M[j]:
                        M[j] = val

            cur = f[i + 1]
            prev = f[i]
            pi = P[i + 1]
            for j in range(k + 1):
                best = prev[j]
                if j >= 1:
                    cand = M[j] + pi
                    if cand > best:
                        best = cand
                cur[j] = best

        return f[n][k]
