import numpy as np

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        NEG = -10**15
        K = k + 1
        # F[L] is array over j (number of subarrays started), L in 0..m
        F = [np.full(K, NEG, dtype=np.int64) for _ in range(m + 1)]
        F[0][0] = 0
        for x in nums:
            closable = np.maximum(F[0], F[m])
            new = [np.full(K, NEG, dtype=np.int64) for _ in range(m + 1)]
            new[0] = closable.copy()
            # start a new subarray with x
            start = np.full(K, NEG, dtype=np.int64)
            start[1:] = closable[:-1] + x
            new[1] = np.maximum(new[1], start)
            # extend open subarrays
            for L in range(1, m + 1):
                target = min(L + 1, m)
                cand = F[L] + x
                new[target] = np.maximum(new[target], cand)
            F = new
        return int(max(F[0][k], F[m][k]))
