        n = len(nums)
        P = [0] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] + nums[i]
        NEG = -10 ** 18
        HALF = NEG // 2
        prev = [0] * (n + 1)  # f[0][i] = 0
        for j in range(1, k + 1):
            cur = [NEG] * (n + 1)
            best = NEG
            for i in range(n + 1):
                s = i - m
                if s >= 0 and prev[s] > HALF:
                    val = prev[s] - P[s]
                    if val > best:
                        best = val
                g = best + P[i] if best > HALF else NEG
                left = cur[i - 1] if i > 0 else NEG
                cur[i] = g if g > left else left
            prev = cur
        return prev[n]
