        dp = [None] * (n + 1)
        dp[0] = [NEG] * (k + 1)
        dp[0][0] = 0
        g = [NEG] * (k + 1)

        for i in range(1, n + 1):
            s = i - m
            if s >= 0:
                prev = dp[s]
                ps = P[s]
                for j in range(1, k + 1):
                    v = prev[j - 1] - ps
                    if v > g[j]:
                        g[j] = v
            cur = dp[i - 1][:]
            cur[0] = 0
            pi = P[i]
            for j in range(1, k + 1):
                if g[j] != NEG:
                    cand = pi + g[j]
                    if cand > cur[j]:
                        cur[j] = cand
            dp[i] = cur

        return int(dp[n][k])

